var timerId = null;
self.onmessage = function(e) {
  var type = e.data.type;
  var interval = e.data.interval;
  if (type === 1) {
    if (timerId) clearInterval(timerId);
    timerId = setInterval(function() {
      self.postMessage({ type: 3 });
    }, interval);
  } else if (type === 2) {
    if (timerId) {
      clearInterval(timerId);
      timerId = null;
    }
  }
};
